function nthUglyNumber(n) {
  const dp = new Array(n);
  dp[0] = 1;
  let i2 = 0;
  let i3 = 0;
  let i5 = 0;

  for (let k = 1; k < n; k++) {
    const next2 = dp[i2] * 2;
    const next3 = dp[i3] * 3;
    const next5 = dp[i5] * 5;
    dp[k] = Math.min(next2, next3, next5);
    if (dp[k] === next2) i2++;
    if (dp[k] === next3) i3++;
    if (dp[k] === next5) i5++;
  }
  return dp[n - 1];
}

