function nthUglyNumber(n) {
  // Every ugly number is 2^a * 3^b * 5^c; list all of them below 2^31 and sort.
  const limit = 2 ** 31;
  const all = [];
  for (let a = 1; a < limit; a *= 2)
    for (let b = a; b < limit; b *= 3)
      for (let c = b; c < limit; c *= 5) all.push(c);
  all.sort((x, y) => x - y);
  return all[n - 1];
}

